19	/**
20	 * Rebuild today's stored looks for the screen, or return null if they can no
21	 * longer be rendered faithfully.
22	 *
23	 * Garment details (brand, name, colours) are read LIVE from `itemsById` rather
24	 * than from the stored row, so renaming an item in the closet is reflected in
25	 * today's look. Only the stylist's decisions — which items, in which slots, in
26	 * which order, and what it said about them — come from storage.
27	 *
28	 * Returning null (rather than a partial look) is deliberate: a closet edit
29	 * during the day must produce a fresh complete outfit, never one with a hole.
30	 */
31	export function reassembleLooks(
32	  stored: StoredLook[],
33	  itemsById: Map<string, ItemRow>,
34	  signed: Map<string, string>,
35	  pathFor: (itemId: string) => string | undefined,
36	): Look[] | null {
37	  const looks: Look[] = [];
38	
39	  for (const s of stored) {
40	    const pieces: LookPiece[] = [];
41	    for (const p of s.pieces) {
42	      const item = itemsById.get(p.itemId);
43	      if (!item) return null; // item left the closet
44	      const path = pathFor(p.itemId);
45	      const url = path ? signed.get(path) : undefined;
46	      if (!url) return null; // image no longer signable
47	      pieces.push({
48	        itemId: item.id,
49	        category: item.category,
50	        subcategory: item.subcategory ?? null,
51	        brand: item.brand ?? null,
52	        name: item.name ?? null,
53	        colors: item.colors ?? [],
54	        cutoutUrl: url,
55	        slot: p.slot,
56	      });
57	    }
58	    looks.push({ name: s.lookName, why: s.why, pieces, anchorIndex: s.anchorIndex });
59	  }
60	
61	  return looks;
62	}
