34	export async function generate(input: {
35	  occasion: UiOccasion;
36	  formality: number | null;
37	  /** Refine "Lean into" colour families (`COLOR_FAMILIES` keys). A preference, not a filter. */
38	  lean: string[];
39	  /** Explicit user action only — the one way to spend an AI call on a day already answered. */
40	  regenerate?: boolean;
41	  city?: { lat: number; lon: number; label: string; source: LocationSource };
42	}): Promise<GenerateResult> {
43	  try {
44	    const supabase = await createClient();
45	    const {
46	      data: { user },
47	    } = await supabase.auth.getUser();
48	    if (!user) return { status: "error", message: "Not signed in" };
49	
50	    const { data: profile } = await supabase
51	      .from("profiles")
52	      .select(
53	        "archetype, formality_min, formality_max, location_lat, location_lon, location_label, location_source",
54	      )
55	      .eq("id", user.id)
56	      .single();
57	    const { data: itemsRaw } = await supabase
58	      .from("items")
59	      .select("*")
60	      .eq("user_id", user.id)
61	      .eq("archived", false);
62	    const items = itemsRaw ?? [];
63	    const byId = new Map(items.map((i) => [i.id, i]));
64	
65	    const loc = resolveLocation({ input: input.city, profile });
66	
67	    const now = new Date();
68	    const f = await fetchForecast(loc.lat, loc.lon);
69	    const advice = laterAdvice(f.hourly);
70	    const weather: WeatherPayload = {
71	      tempC: f.tempC,
72	      feelsLikeC: f.feelsLikeC,
73	      condition: f.condition,
74	      cityLabel: loc.label,
75	      timezone: f.timezone,
76	      locationOrigin: loc.origin,
77	      laterSentence: advice.sentence,
78	      adviceClause: advice.adviceClause,
79	      laterLabel: "Later",
80	      hourly: f.hourly,
81	    };
82	
83	    const today = localDateFor(now, f.timezone);
84	
85	    // The daily drop (Decision 5): today's looks are generated once and then
86	    // read back. Only an explicit regenerate spends an AI call on a day the
87	    // stylist has already answered.
88	    //
89	    // The stored set is read on BOTH paths. On a normal load it IS the answer;
90	    // on a regenerate it is the recency signal — the pieces the user just
91	    // rejected, which ranking will sink without ever filtering them out.
92	    const stored = await loadDailyLooks(user.id, input.occasion, today);
93	
94	    if (!input.regenerate && stored?.length) {
95	      const paths = Array.from(
96	        new Set(
97	          stored
98	            .flatMap((s) => s.pieces.map((p) => byId.get(p.itemId)))
99	            .filter((it): it is NonNullable<typeof it> => Boolean(it))
100	            .map((it) => displayPath(it)),
101	        ),
102	      );
103	      const signed = await signItemImages(paths);
104	      const looks = reassembleLooks(stored, byId, signed, (id) => {
105	        const it = byId.get(id);
106	        return it ? displayPath(it) : undefined;
107	      });
108	      // null = the closet changed under the stored set; fall through and
109	      // regenerate rather than showing an outfit with a hole in it.
110	      if (looks) return { status: "ok", weather, looks };
111	    }
112	
113	    // Only a deliberate regenerate carries the signal. A fall-through from a
114	    // stale stored set is the app fixing itself, not the user asking for
115	    // something else — penalising those pieces would be arbitrary.
116	    const recentlyShown = input.regenerate
117	      ? Array.from(new Set(stored?.flatMap((s) => s.pieces.map((p) => p.itemId)) ?? []))
118	      : [];
119	
120	    await assertCanGenerate(user.id);
121	
122	    const candItems: CandidateItem[] = items.map((i) => ({
123	      id: i.id,
124	      category: i.category,
125	      colors: i.colors ?? [],
126	      formality: i.formality,
127	      seasons: i.seasons ?? [],
128	      material: i.material,
129	    }));
130	    // Occasion gives the context; the user's onboarding dress codes narrow it;
131	    // an explicit Refine formality overrides both.
132	    const band = applyFormalityOverride(
133	      personalBand(input.occasion, profile),
134	      input.formality,
135	    );
136	    const candidateArgs = {
137	      band,
138	      weather: { tempC: f.tempC, rain: f.hourly.some((h) => h.isNow && h.rain) },
139	      season: currentSeason(now),
140	      excludeItemIds: [],
141	      maxAccessories: 1,
142	    };
143	    const combos = buildCandidates(candItems, candidateArgs);
144	    if (combos.length === 0) {
145	      return { status: "empty", weather, missing: missingCategory(candItems, candidateArgs) };
146	    }
147	
148	    const aesthetic = profile?.archetype ? [profile.archetype] : [];
149	    // The Refine colour pick lands here, in ranking — not in candidate building.
150	    // It reorders the shortlist toward the requested families and is dropped
151	    // silently when the closet cannot honour it.
152	    //
153	    // Rank everything, then spread the shortlist across the wardrobe before the
154	    // re-ranker sees it. Taking the top 20 by score alone clusters — a neutral
155	    // top harmonises with everything, so it occupies most of the list, and "the
156	    // best 3" of a clustered list is three versions of one outfit. Diversifying
157	    // the INPUT makes the model's three distinct by construction.
158	    // Season rides along as a ranking preference — in-season combos float to the
159	    // top of the shortlist the re-ranker sees, but an off-season one is still
160	    // offered rather than the screen going empty.
161	    const ranked = rankTopN(
162	      combos,
163	      { aesthetic, band, lean: input.lean, recentlyShown, season: candidateArgs.season },
164	      combos.length,
165	    );
166	    const top = diversify(ranked, 20);
167	
168	    const { picks } = await rerank({
169	      combos: top.map((t) =>
170	        t.items.map((ci) => {
171	          const it = byId.get(ci.id)!;
172	          return { category: it.category, subcategory: it.subcategory, colors: it.colors ?? [] };
173	        }),
174	      ),
175	      aesthetic,
176	      occasion: input.occasion,
177	      weatherLabel: f.condition,
178	      tempC: f.tempC,
179	    });
180	
181	    const paths = Array.from(
182	      new Set(top.flatMap((t) => t.items.map((ci) => displayPath(byId.get(ci.id)!)))),
183	    );
184	    const signed = await signItemImages(paths);
185	
186	    // `rerank` already dropped picks that repeat a combo or point outside the
187	    // shortlist, so every index here resolves. It previously fell back to
188	    // `top[0]` for an unknown index, which turned a bad index into a duplicate
189	    // of the first look rather than into one fewer look.
190	    const looks: Look[] = picks.map((p) => {
191	      const combo = top[p.combo_index].items;
192	      const dbItems = combo.map((ci) => byId.get(ci.id)!);
193	      const slots = layoutForLook(dbItems.map((d) => ({ category: d.category })));
194	      const pieces: LookPiece[] = dbItems.map((d, idx) => ({
195	        itemId: d.id,
196	        category: d.category,
197	        subcategory: d.subcategory ?? null,
198	        brand: d.brand ?? null,
199	        name: d.name ?? null,
200	        colors: d.colors ?? [],
201	        cutoutUrl: signed.get(displayPath(d)) ?? "",
202	        slot: slots[idx],
203	      }));
204	      return { name: p.name, why: p.why, pieces, anchorIndex: staggerOrder(slots)[0] };
205	    });
206	
207	    // Fire-and-forget would be simpler, but a failed write means the user pays
208	    // for another AI call on their next tap — worth awaiting.
209	    await saveDailyLooks(user.id, input.occasion, today, weather, looks);
210	
211	    return { status: "ok", weather, looks };
212	  } catch (e) {
213	    console.error("[generate] failed:", e);
214	    return { status: "error", message: e instanceof Error ? e.message : "Generation failed" };
215	  }
216	}
