251	export async function predictDefaultOccasion(): Promise<{ occasion: UiOccasion; reason: string }> {
252	  const supabase = await createClient();
253	  const {
254	    data: { user },
255	  } = await supabase.auth.getUser();
256	  if (!user) return { occasion: "everyday", reason: defaultReason("everyday") };
257	
258	  const { data: profile } = await supabase
