import { freshIndexStart, isWornToday, wearLabel } from "../wear";

test("the button says what it will do, then what it did", () => {
  // Design :362 — wearLabel is dynamic, so the button reflects state.
  expect(wearLabel(false)).toBe("Wear this today");
  expect(wearLabel(true)).toBe("Worn today");
});

test("a wear counts for today only when its local date matches", () => {
  expect(isWornToday([{ worn_on: "2026-07-24" }], "2026-07-24")).toBe(true);
  expect(isWornToday([{ worn_on: "2026-07-23" }], "2026-07-24")).toBe(false);
  expect(isWornToday([], "2026-07-24")).toBe(false);
});

test("an outfit worn on several days is still worn today if one of them is today", () => {
  expect(isWornToday([{ worn_on: "2026-07-01" }, { worn_on: "2026-07-24" }], "2026-07-24")).toBe(
    true,
  );
});

// The pin: a worn outfit survives a Regenerate, so the new set has to be placed
// AROUND it. outfits_daily_unique is (user_id, occasion, generated_on,
// look_index), so reusing a pinned index is a constraint violation, not a
// cosmetic clash.
test("a regenerate with nothing pinned starts at zero, exactly as before", () => {
  expect(freshIndexStart([])).toBe(0);
});

test("a regenerate places the new set past every pinned index", () => {
  expect(freshIndexStart([0])).toBe(1);
  expect(freshIndexStart([1])).toBe(2);
  // Two worn looks, and the gap at 1 is deliberately not reused — indices only
  // ever move forward, so a second regenerate cannot collide with the first.
  expect(freshIndexStart([0, 2])).toBe(3);
});

test("a pinned look with no index does not drag the new set back to zero", () => {
  // look_index is nullable in the schema; a null must not read as index 0.
  expect(freshIndexStart([null, 3])).toBe(4);
  expect(freshIndexStart([null])).toBe(0);
});

/**
 * Wear logging — the one write path every wear-derived surface reads from.
 *
 * Times worn, cost-per-wear, last worn, the Fit Diary grid, streaks, "most
 * worn" and "gathering dust" are all views over wear_logs. Nothing wrote to it
 * before this.
 */

/** The button states itself: an instruction before, a fact after. */
export function wearLabel(worn: boolean): string {
  return worn ? "Worn today" : "Wear this today";
}

/**
 * `worn_on` is a DATE column, compared against the user's LOCAL date key — a
 * UTC comparison would move an evening wear in an eastern timezone onto the
 * next day, which is the same class of bug the daily drop already avoids.
 */
export function isWornToday(logs: { worn_on: string }[], today: string): boolean {
  return logs.some((l) => l.worn_on === today);
}

/**
 * Where a regenerated set starts numbering, given the indices already pinned.
 *
 * A worn outfit is pinned: `saveDailyLooks` leaves it out of the day's delete so
 * that wearing a look and then regenerating cannot destroy what you actually
 * wore (the FK had no ON DELETE action, so it used to fail outright). But
 * `outfits_daily_unique` is `(user_id, occasion, generated_on, look_index)`, so
 * the fresh set has to be numbered past the survivors.
 *
 * Indices only ever move forward — gaps left by a previous regenerate are not
 * reused, because reusing one would collide with a look pinned in between.
 */
export function freshIndexStart(pinned: (number | null)[]): number {
  const used = pinned.filter((i): i is number => typeof i === "number");
  return used.length === 0 ? 0 : Math.max(...used) + 1;
}

import { createClient } from "@/lib/supabase/server";
import type { Look, WeatherPayload } from "@/lib/generator/types";
import type { StoredLook } from "./reassemble";
import { freshIndexStart, isWornToday } from "./wear";

/** Today's stored set for one occasion, in the order the stylist chose. */
export async function loadDailyLooks(
  userId: string,
  occasion: string,
  generatedOn: string,
): Promise<StoredLook[] | null> {
  const supabase = await createClient();
  const { data } = await supabase
    .from("outfits")
    // `wear_logs(worn_on)` is the reverse of wear_logs.outfit_id. A look the
    // user has already worn today stays in the set and is badged, rather than
    // disappearing the moment they tap the button.
    .select("id, look_name, ai_reasoning, layout, look_index, wear_logs(worn_on)")
    .eq("user_id", userId)
    .eq("occasion", occasion)
    .eq("generated_on", generatedOn)
    .order("look_index", { ascending: true });

  if (!data || data.length === 0) return null;

  return data.map((row) => {
    const layout = (row.layout ?? {}) as {
      anchorIndex?: number;
      pieces?: StoredLook["pieces"];
    };
    return {
      id: row.id,
      lookName: row.look_name ?? "",
      why: row.ai_reasoning ?? "",
      anchorIndex: layout.anchorIndex ?? 0,
      pieces: layout.pieces ?? [],
      worn: isWornToday(row.wear_logs ?? [], generatedOn),
    };
  });
}

/**
 * Replace today's set for one occasion. Delete-then-insert rather than upsert:
 * a regenerate may return a different NUMBER of looks, and leftovers from the
 * previous set must not survive alongside the new one.
 *
 * One exception, and it is the reason this function can be called at all after
 * a wear: an outfit with a wear log is PINNED. `wear_logs.outfit_id` used to
 * have no ON DELETE action, so deleting a worn outfit raised a foreign-key
 * violation and the whole regeneration failed. Pinning is also the honest
 * product behaviour — what you actually wore today is not a suggestion to be
 * thrown away, so it keeps its place in the day's set and the fresh looks are
 * numbered past it (`outfits_daily_unique` covers `look_index`).
 *
 * Returns the new outfit ids, aligned with the `looks` array.
 */
export async function saveDailyLooks(
  userId: string,
  occasion: string,
  generatedOn: string,
  weather: WeatherPayload,
  looks: Look[],
): Promise<string[]> {
  const supabase = await createClient();

  const { data: existing } = await supabase
    .from("outfits")
    .select("id, look_index, wear_logs(worn_on)")
    .eq("user_id", userId)
    .eq("occasion", occasion)
    .eq("generated_on", generatedOn);

  // Any wear log pins the row — not just today's. The point is that nothing
  // referenced by wear_logs is ever deleted here.
  const pinned = (existing ?? []).filter((r) => (r.wear_logs ?? []).length > 0);

  let del = supabase
    .from("outfits")
    .delete()
    .eq("user_id", userId)
    .eq("occasion", occasion)
    .eq("generated_on", generatedOn);
  if (pinned.length) del = del.not("id", "in", `(${pinned.map((r) => r.id).join(",")})`);
  await del;

  const start = freshIndexStart(pinned.map((r) => r.look_index));
  const rows = looks.map((look, i) => ({
    user_id: userId,
    occasion,
    generated_on: generatedOn,
    look_index: start + i,
    look_name: look.name,
    ai_reasoning: look.why,
    weather_snapshot: weather,
    layout: {
      anchorIndex: look.anchorIndex,
      pieces: look.pieces.map((p) => ({ itemId: p.itemId, slot: p.slot })),
    },
  }));

  const { data: inserted } = await supabase
    .from("outfits")
    .insert(rows)
    .select("id, look_index");
  if (!inserted) return [];

  // outfit_items is the relational record — it is what wear_logs and future
  // analytics join against. The renderable geometry lives in outfits.layout.
  const links = inserted.flatMap((row) => {
    const look = looks[row.look_index - start];
    return (look?.pieces ?? []).map((p) => ({
      outfit_id: row.id,
      item_id: p.itemId,
      slot: p.category,
    }));
  });
  if (links.length) await supabase.from("outfit_items").insert(links);

  // Insert order is not guaranteed — place each id at its look's position.
  const ids: string[] = [];
  for (const row of inserted) ids[row.look_index - start] = row.id;
  return ids;
}

