import { pinItem, styledLookName } from "../styled";

const combo = (...ids: string[]) => ({ items: ids.map((id) => ({ id })) });

test("keeps only the combos that actually contain the piece", () => {
  const combos = [combo("a", "b"), combo("b", "c"), combo("a", "c")];
  expect(pinItem(combos, "a")).toHaveLength(2);
  expect(pinItem(combos, "a").every((c) => c.items.some((i) => i.id === "a"))).toBe(true);
});

test("preserves the ranked order it was given", () => {
  const combos = [combo("a", "x"), combo("q"), combo("a", "y")];
  expect(pinItem(combos, "a").map((c) => c.items[1].id)).toEqual(["x", "y"]);
});

// The caller uses this to decide whether to widen the formality band before
// giving up — an empty array is a real answer, not a failure.
test("a piece that fits no combo returns empty rather than throwing", () => {
  expect(pinItem([combo("a"), combo("b")], "zzz")).toEqual([]);
  expect(pinItem([], "a")).toEqual([]);
});

// The model names the look, but a name must exist even if that call is skipped
// or the schema repair drops the pick.
test("the fallback name is built from the piece, never left blank", () => {
  expect(styledLookName({ name: "Brushed Oxford", subcategory: "Oxford shirt", category: "Tops" }))
    .toBe("Around the Brushed Oxford");
  expect(styledLookName({ name: null, subcategory: "Oxford shirt", category: "Tops" })).toBe(
    "Around the Oxford shirt",
  );
  expect(styledLookName({ name: null, subcategory: null, category: "Tops" })).toBe(
    "Around the Tops",
  );
});

/**
 * "Style an outfit with this" — the pure parts.
 *
 * Deliberately free of any Supabase import so it stays testable under jsdom;
 * the persistence lives in `styled-store.ts`.
 */

/**
 * Narrow a ranked candidate list to the combos containing one piece.
 *
 * This is the whole of "pin the item": the generator already builds every valid
 * combination and ranks it, so styling around a chosen piece is a filter over
 * that work, not a second algorithm. Order is preserved, so the best combo
 * containing the piece stays the best.
 *
 * Returns empty when the piece fits nothing under the current band — the caller
 * widens the formality band and tries again rather than treating that as an
 * error, the same "a hard filter must never empty a required slot" rule the
 * generator already follows.
 */
export function pinItem<T extends { items: { id: string }[] }>(combos: T[], itemId: string): T[] {
  return combos.filter((c) => c.items.some((i) => i.id === itemId));
}

/**
 * The name to fall back to when the model does not supply one.
 *
 * A look with no name renders a blank headline on both the detail screen and
 * the index tabs, so there is always a name — built from the piece the look was
 * styled around, which is also the honest description of it.
 */
export function styledLookName(item: {
  name: string | null;
  subcategory: string | null;
  category: string;
}): string {
  return `Around the ${item.name ?? item.subcategory ?? item.category}`;
}

import { createClient } from "@/lib/supabase/server";
import type { LookDraft, WeatherPayload } from "@/lib/generator/types";

/**
 * The cache read for "Style an outfit with this".
 *
 * `outfits_styled_unique (user_id, styled_item_id, generated_on)` means there is
 * at most one row per piece per local day, so this is the whole cache: a hit
 * costs one indexed lookup and NO model call.
 */
export async function loadStyledLook(
  userId: string,
  itemId: string,
  generatedOn: string,
): Promise<string | null> {
  const supabase = await createClient();
  const { data } = await supabase
    .from("outfits")
    .select("id")
    .eq("user_id", userId)
    .eq("styled_item_id", itemId)
    .eq("generated_on", generatedOn)
    .maybeSingle();
  return data?.id ?? null;
}

/**
 * Persist a styled look and return its id.
 *
 * `look_index` is deliberately left NULL: `outfits_daily_unique` covers
 * (user_id, occasion, generated_on, look_index), and Postgres treats NULLs as
 * distinct, so two pieces styled on the same day for the same occasion cannot
 * collide. `loadDailyLooks`/`saveDailyLooks` filter these rows out entirely.
 */
export async function saveStyledLook(
  userId: string,
  itemId: string,
  occasion: string,
  generatedOn: string,
  weather: WeatherPayload,
  look: LookDraft,
): Promise<string | null> {
  const supabase = await createClient();

  const { data: row } = await supabase
    .from("outfits")
    .insert({
      user_id: userId,
      occasion,
      generated_on: generatedOn,
      styled_item_id: itemId,
      look_name: look.name,
      ai_reasoning: look.why,
      weather_snapshot: weather,
      layout: {
        anchorIndex: look.anchorIndex,
        pieces: look.pieces.map((p) => ({ itemId: p.itemId, slot: p.slot })),
      },
    })
    .select("id")
    .single();
  if (!row) return null;

  const links = look.pieces.map((p) => ({
    outfit_id: row.id,
    item_id: p.itemId,
    slot: p.category,
  }));
  if (links.length) await supabase.from("outfit_items").insert(links);

  return row.id;
}

